content.tokens_css:
/* 极简墨白 — 唤星官方内置设计系统（四层 token 契约真源） */
:root {
  --bg: #ffffff;
  --surface: #f7f7f8;
  --surface-warm: #fafafa;
  --fg: #111113;
  --fg-2: #1f1f23;
  --muted: #6b6b73;
  --meta: #9a9aa3;
  --border: #e7e7ea;
  --border-soft: #f0f0f2;
  --accent: #111113;
  --accent-on: #ffffff;
  --accent-hover: #2a2a30;
  --accent-active: #000000;
  --success: #16a34a;
  --warn: #d97706;
  --danger: #dc2626;
  --font-display: "Songti SC", "Source Han Serif SC", Georgia, ui-serif, serif;
  --font-body: "PingFang SC", "Inter", system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-mono: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Monaco, Consolas, monospace;
  --text-xs: 12px;
  --text-sm: 13px;
  --text-base: 16px;
  --text-lg: 18px;
  --text-xl: 20px;
  --text-2xl: 28px;
  --text-3xl: 36px;
  --text-4xl: 48px;
  --leading-body: 1.6;
  --leading-tight: 1.2;
  --tracking-display: -0.01em;
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-8: 32px;
  --space-12: 48px;
  --section-y-desktop: 96px;
  --section-y-tablet: 64px;
  --section-y-phone: 48px;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-pill: 9999px;
  --elev-flat: none;
  --elev-ring: 0 0 0 1px var(--border);
  --elev-raised: 0 8px 24px color-mix(in oklab, var(--fg), transparent 90%);
  --focus-ring: 0 0 0 3px color-mix(in oklab, var(--accent), transparent 70%);
  --motion-fast: 150ms;
  --motion-base: 200ms;
  --ease-standard: cubic-bezier(0.2, 0, 0, 1);
  --container-max: 1200px;
  --container-gutter-desktop: 40px;
  --container-gutter-tablet: 24px;
  --container-gutter-phone: 20px;
}

